"use client";
import { useEffect, useId, useRef, useState } from "react";
import { useTypeMotion, type TypographyMotionProps, typeInteractive } from "./typography-shared";
import { typeStaggerProgress } from "./typography-math";
export interface TextOnPathProps extends TypographyMotionProps {
  fontSize?: number;
  curveSpread?: number;
  path?: string;
  viewBox?: string;
  startOffset?: number;
}
/** SVG's actual text path bends glyph baselines along the consumer-supplied curve. */
export function TextOnPath({
  text = "The fastest line is never straight, every turn takes you somewhere new.",
  fontSize = 35,
  curveSpread = 150,
  path,
  viewBox,
  startOffset = 0,
  ...props
}: TextOnPathProps) {
  const id = useId().replace(/:/g, ""),
    root = useRef<HTMLDivElement>(null);
  const [compact, setCompact] = useState(false);
  useEffect(() => {
    let disposed = false;
    const measure = () => {
      if (!disposed && root.current) setCompact(root.current.clientWidth < 650);
    };
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(measure);
    (document.fonts?.ready ?? Promise.resolve()).then(() => {
      if (!disposed && root.current) {
        measure();
        observer?.observe(root.current);
      }
    });
    return () => {
      disposed = true;
      observer?.disconnect();
    };
  }, []);
  const amplitude = Math.min(140, curveSpread);
  const compactCurve = `M 20 160 C 100 ${160 - amplitude} 220 ${160 - amplitude} 300 160 S 500 ${160 + amplitude} 600 160 C 610 230 600 370 530 380 C 420 ${380 + amplitude * 0.6} 380 ${380 - amplitude * 0.6} 280 380 S 100 ${380 + amplitude * 0.6} 20 380`;
  const curve =
    path ??
    (compact && !viewBox
      ? compactCurve
      : `M -10 280 C 100 280 130 ${210 - curveSpread} 300 ${210 - curveSpread} S 460 ${210 + curveSpread} 650 ${210 + curveSpread} S 890 ${210 - curveSpread} 1070 ${210 - curveSpread} S 1320 300 1400 210`);
  useTypeMotion(
    root,
    props,
    (p, reduced) => {
      const svg = root.current!.querySelector("svg")!;
      const fallback = root.current!.querySelector<HTMLElement>("[data-type-path-fallback]")!;
      svg.style.display = reduced ? "none" : "block";
      fallback.style.display = reduced ? "block" : "none";
      const words = root.current!.querySelectorAll<SVGTSpanElement>("tspan");
      words.forEach(
        (word, i) => (word.style.opacity = String(typeStaggerProgress(p, i, words.length, 0.85))),
      );
    },
    `${text}:${curve}:${fontSize}`,
  );
  return (
    <div
      ref={root}
      className={props.className}
      style={{ width: "100%", ...props.style }}
      data-typography="text-on-path"
      {...typeInteractive(props.trigger)}
    >
      <span
        data-type-path-fallback=""
        style={{ display: "none", fontSize, letterSpacing: "-.02em", fontWeight: 400 }}
      >
        {text}
      </span>
      <svg
        viewBox={viewBox ?? (compact ? "0 0 620 560" : "0 0 1200 420")}
        style={{ width: "100%", height: "auto", overflow: "visible" }}
        role="img"
        aria-label={text}
      >
        <title>{text}</title>
        <defs>
          <path id={`z-type-path-${id}`} d={curve} />
        </defs>
        <text
          fill="currentColor"
          fontSize={fontSize}
          fontWeight={400}
          letterSpacing={0}
          xmlSpace="preserve"
          aria-hidden="true"
        >
          <textPath href={`#z-type-path-${id}`} startOffset={`${startOffset}%`}>
            {text.split(/(\s+)/).map((word, i) => (
              <tspan key={i}>{word}</tspan>
            ))}
          </textPath>
        </text>
      </svg>
    </div>
  );
}
